<template>
  <view class="page"><SiteHeader active="saved"/><view class="wrap">
    <text class="title">我的</text><text class="subtitle">回看你的模拟体验，收藏感兴趣的文章和线下活动。</text><text class="hint">记录只保存在当前浏览器，换设备不会自动同步。</text>
    <view class="my-summary"><view><text>{{history.length}}</text><small>场模拟记录</small></view><view><text>{{unlocked.size}} / 24</text><small>已点亮人格</small></view><view><text>{{remainingGames}}</text><small>个项目尚未体验</small></view><view><text>{{savedArticles.length}}</text><small>篇收藏文章</small></view></view>
    <view class="collection"><view class="block-head"><view><text class="block-title">我的副业人格图鉴</text><text class="block-sub">完成模拟后，点亮属于你的趣味人格。</text></view><text>{{unlocked.size}} / 24</text></view><view class="persona-grid"><view v-for="(p,index) in personas" :key="index" class="persona-cell" :class="{unlocked:unlocked.has(index)}"><view class="persona-icon"><image v-if="unlocked.has(index)" :src="p.icon" mode="aspectFit"/><text v-else>?</text></view><text>{{unlocked.has(index)?p.name:'待解锁'}}</text></view></view></view>
    <view class="collection"><view class="block-head"><view><text class="block-title">我的模拟战报</text><text class="block-sub">仅保存在当前浏览器，最多保留 50 条。</text></view></view><view v-for="(record,index) in history" :key="index" class="history-row"><view class="history-info"><text class="history-title">{{record.persona || '实践探索者'}} · {{record.result || '体验完成'}}</text><text class="history-meta">{{record.project || 'AI 项目模拟'}} · {{formatPlayed(record.time)}}</text></view><button @click="selectedRecord=record">查看</button><button @click="replay(record)">再玩一次</button></view><view v-if="!history.length" class="empty">还没有模拟记录，体验后可以在这里看到结果。<button @click="goSimulate">去体验项目 →</button></view></view>
    <view v-if="selectedRecord" class="record-overlay" @click="selectedRecord=null"><view class="record-modal" @click.stop><button class="record-close" aria-label="关闭" @click="selectedRecord=null">×</button><text class="record-label">已保存的模拟结果</text><text class="record-title">{{selectedRecord.persona || '实践探索者'}} · {{selectedRecord.result || '体验完成'}}</text><text class="record-project">{{selectedRecord.project}} · {{formatPlayed(selectedRecord.time)}}</text><text v-if="typeof selectedRecord.amount==='number'" class="record-amount">模拟收益 ¥{{selectedRecord.amount}}</text><text class="record-disclaimer">金额为游戏设定，不是收入预测。此处展示已保存的摘要，完整过程不会被恢复。</text><view v-if="Array.isArray(selectedRecord.issues) && selectedRecord.issues.length" class="record-issues"><text>本局回顾</text><text v-for="(issue,i) in selectedRecord.issues.slice(0,3)" :key="i">{{issue}}</text></view><button class="record-replay" @click="replay(selectedRecord)">再体验一次 →</button></view></view>
    <view class="block-head saved-head"><view><text class="block-title">我的收藏</text><text class="block-sub">随时回来继续看。</text></view></view>
    <view class="tabs"><button :class="{on:tab==='article'}" @click="tab='article'">文章 {{savedArticles.length}}</button><button :class="{on:tab==='event'}" @click="tab='event'">线下活动 {{savedEvents.length}}</button></view>
    <view v-if="tab==='article'"><view v-for="a in savedArticles" :key="a.id" class="row" @click="openArticle(a)"><text class="kind">{{a.kind || '分享'}} · {{a.author}}</text><text class="name">{{a.title}}</text><text class="summary">{{a.overview||a.summary}}</text><view class="row-bottom"><text>查看导读 →</text><text @click.stop="remove('article',a)">取消收藏</text></view></view><view v-if="!savedArticles.length" class="empty">还没有收藏文章。<button @click="goDiscover">去发现</button></view></view>
    <view v-else><view v-for="e in savedEvents" :key="e.id" class="row"><text class="kind">{{e.city}} · {{e.typeText || '活动'}}</text><text class="name">{{e.name}}</text><text class="summary">{{e.summary||e.description}}</text><view class="row-bottom"><text @click="goEvents">在线下活动页查看 →</text><text @click="remove('event',e)">取消收藏</text></view></view><view v-if="!savedEvents.length" class="empty">还没有收藏线下活动。<button @click="goEvents">查看线下活动</button></view></view>
    <JoinOffer variant="inline" from="mine" />
    <view class="data-notice">为了解模拟体验和体验营入口的使用情况，本网站会记录页面与按钮事件，并在本机保存随机标识；不记录输入内容或完整网址，记录约保留 90 天。</view>
  </view><CampFooter/></view>
</template>
<script setup>
import {computed,ref,onMounted,onUnmounted} from 'vue';import {onShow} from '@dcloudio/uni-app';
import JoinOffer from '../../components/JoinOffer.vue';
import SiteHeader from '../../components/SiteHeader.vue';import CampFooter from '../../components/CampFooter.vue';
import {articles,events} from '../../data/content.js';import {getSaved,setSaved} from '../../data/storage.js';import personas from '../../data/personas.json';
import {caseStudies,caseAsArticle} from '../../data/case-studies.js';
const tab=ref('article'),saved=ref([]),history=ref([]),selectedRecord=ref(null);
function readLocal(key){try{let v=uni.getStorageSync(key);if(typeof v==='string')return v?JSON.parse(v):null;return v||null}catch{return null}}
onShow(()=>{saved.value=getSaved();let v=readLocal('ainpe:history');if(!Array.isArray(v)){const last=readLocal('ainpe:played');v=last&&typeof last==='object'?[last]:[]}history.value=v.filter(x=>x&&typeof x==='object').slice(0,50)});
// #ifdef H5
function dismissRecord(e){if(e.key==='Escape')selectedRecord.value=null}
onMounted(()=>window.addEventListener('keydown',dismissRecord));onUnmounted(()=>window.removeEventListener('keydown',dismissRecord));
// #endif
const unlocked=computed(()=>new Set(history.value.filter(h=>h.personaIndex!==null&&h.personaIndex!==undefined).map(h=>Number(h.personaIndex)).filter(n=>Number.isInteger(n)&&n>=0&&n<24)));
function gameName(record){const raw=String(record?.game||'').replace(/\.html$/,'');if(raw==='voyage-lab'){const p=String(record?.project||'');return /带货/.test(p)?'books':/第二大脑/.test(p)?'brain':/热词/.test(p)?'trends':''}return raw}
const remainingGames=computed(()=>Math.max(0,6-new Set(history.value.map(gameName).filter(x=>['miniapp','video','education-ppt','books','brain','trends'].includes(x))).size));
const savedArticles=computed(()=>{const curated=caseStudies.map(caseAsArticle),ids=new Set(curated.map(a=>a.id));return [...curated,...articles.filter(a=>!ids.has(String(a.id)))].filter(a=>saved.value.includes(`article:${a.id}`))});
const savedEvents=computed(()=>events.filter(e=>saved.value.includes(`event:${e.id}`)));
function formatPlayed(value){const d=new Date(value);return Number.isNaN(d.getTime())?'时间未记录':`${d.getFullYear()}/${d.getMonth()+1}/${d.getDate()}`}
function remove(t,item){saved.value=saved.value.filter(k=>k!==`${t}:${item.id}`);setSaved(saved.value)}
function openArticle(a){uni.navigateTo({url:`/pages/article/index?id=${encodeURIComponent(a.id)}`})}
function goSimulate(){uni.navigateTo({url:'/pages/simulate/index'})}
function replay(record){
// #ifdef H5
const game=gameName(record),classic=['miniapp','video','education-ppt'],other=['books','brain','trends'];if(classic.includes(game)){window.location.href=`/static/simulation-games/${game}.html`;return;}if(other.includes(game)){window.location.href=`/static/simulation-games/voyage-lab.html?project=${game}`;return;}
// #endif
goSimulate()}
function goDiscover(){uni.redirectTo({url:'/pages/discover/index'})}function goEvents(){uni.redirectTo({url:'/pages/events/index'})}
</script>
<style scoped>
.page{min-height:100vh;background:#f7f3ea;color:#173d2b}.wrap{max-width:1050px;margin:auto;padding:32px 20px 45px}.title,.subtitle,.hint{display:block}.title{font-size:32px;font-weight:800}.subtitle{font-size:14px;line-height:1.7;color:#6c8570;margin-top:8px}.hint{font-size:12px;color:#94a48f;margin-top:5px}.my-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:22px 0}.my-summary view{background:#fff;border:1px solid #e4eade;border-radius:8px;padding:15px}.my-summary text,.my-summary small{display:block}.my-summary text{font-size:22px;font-weight:800;color:#19583b}.my-summary small{font-size:12px;color:#8a9c8a;margin-top:5px}.collection{background:#fff;border:1px solid #e1e9dc;border-radius:8px;padding:20px;margin:15px 0}.block-head{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:#769272;margin-bottom:16px}.block-title,.block-sub{display:block}.block-title{font-size:19px;color:#173d2b;font-weight:800}.block-sub{font-size:12px;color:#8a9c8a;margin-top:5px}.persona-grid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:8px}.persona-cell{min-width:0;border:1px solid #e8eee5;border-radius:7px;background:#f7f8f5;text-align:center;padding:10px 4px;color:#a6b3a3;font-size:11px}.persona-cell.unlocked{background:#e7f3e9;border-color:#cde4d0;color:#1b6942}.persona-icon{display:flex;align-items:center;justify-content:center;margin:0 auto 7px;border-radius:50%;width:32px;height:32px;background:#e9ede6;color:#9eab9b;font-size:20px;font-weight:800}.unlocked .persona-icon{background:#175336;color:#ffcd55}.persona-icon image{width:25px;height:25px}.history-row{display:flex;align-items:center;gap:8px;border-top:1px solid #edf1eb;padding:12px 0}.history-info{flex:1;min-width:0}.history-title,.history-meta{display:block}.history-title{font-size:14px;font-weight:750;color:#244b33}.history-meta{font-size:12px;color:#96a696;margin-top:5px}.history-row button{margin:0;padding:0 10px;line-height:32px;font-size:12px;background:#eef5ec;color:#236342;white-space:nowrap}.record-overlay{position:fixed;inset:0;z-index:9999;background:#07150dcc;display:flex;align-items:center;justify-content:center;padding:20px}.record-modal{position:relative;background:white;border-radius:8px;padding:25px;max-width:480px;width:100%;max-height:85vh;overflow:auto}.record-close{position:absolute;right:12px;top:10px;background:transparent;font-size:25px;line-height:1;padding:0}.record-label,.record-title,.record-project,.record-amount,.record-disclaimer,.record-issues text{display:block}.record-label{font-size:12px;color:#76936c}.record-title{font-size:22px;font-weight:800;margin-top:12px}.record-project,.record-disclaimer{font-size:12px;color:#839685;line-height:1.6;margin-top:8px}.record-amount{font-size:20px;font-weight:800;color:#195c3a;margin-top:14px}.record-issues{background:#f2f7ed;padding:14px;margin-top:14px;font-size:13px;line-height:1.6}.record-issues text{margin:5px 0}.record-replay{margin:16px 0 0;padding:0 14px;display:inline-block;background:#e95d28;color:white;font-size:13px;line-height:38px}.saved-head{margin-top:35px}.tabs{display:flex;gap:8px;margin:14px 0}.tabs button{margin:0;background:#eef4e9;color:#56745b;font-size:13px;line-height:36px}.tabs button.on{background:#235039;color:#fff}.row{background:#fff;border:1px solid #e1e9dc;border-radius:8px;padding:16px;margin-bottom:8px}.kind{font-size:12px;color:#8ca087}.name,.summary{display:block}.name{font-size:16px;font-weight:700;line-height:1.5;margin:8px 0}.summary{font-size:13px;line-height:1.7;color:#708674}.row-bottom{display:flex;justify-content:space-between;color:#5c865f;font-size:12px;margin-top:12px}.empty{padding:20px;color:#859a83;background:#fafcf8;font-size:13px;line-height:1.7}.empty button{margin:10px 0 0;display:inline-block;background:#dcebd3;color:#355d3f;font-size:13px;line-height:36px}.data-notice{margin:20px 0;font-size:12px;line-height:1.7;color:#718779}@media(max-width:700px){.my-summary{grid-template-columns:repeat(2,1fr)}.persona-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.history-row{flex-wrap:wrap}.history-info{flex-basis:100%}}
</style>
